ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| regex("(?i)\\\\(vssadmin|wmic|wbadmin|bcdedit|taskkill|net|sc)\\.exe$", field=ImageFileName)
| case {
    regex("(?i)(delete\\s+shadows|shadowcopy.*delete|delete\\s+catalog|recoveryenabled\\s+no|bootstatuspolicy\\s+ignoreallfailures)", field=CommandLine) | RecoveryAction := "true";
    regex("(?i)(MsMpEng|WinDefend|Defender|Veeam|BackupExec|SQLAgent|MSExchange|VSS|Sophos|memtas|mepocs|SamSs)", field=CommandLine) | KillAction := "true";
    *
  }
| RecoveryAction="true" OR KillAction="true"
| groupBy([aid, ComputerName], function=[count(field=RecoveryAction, as=RecoveryCount, distinct=true), count(field=KillAction, as=KillCount, distinct=true), min(@timestamp, as=FirstSeen), max(@timestamp, as=LastSeen), collect([ImageFileName, CommandLine])])
| RecoveryCount>=1 AND KillCount>=1
| WindowSec := (LastSeen - FirstSeen)/1000
| WindowSec <= 600
